const i={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Blocchi di configurazione Klipper e macro pronti da incollare - sequenze di avvio, gestione del filamento, input shaping, bed mesh e altro. Copiane uno e inseriscilo nel tuo printer.cfg (il Config Editor è un buon posto dove incollarlo)."}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Aiuto"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Informazioni sui modelli di configurazione"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Chiudi"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"Come usarli"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"Filtra per categoria per trovare una macro o un blocco di configurazione."}},{t:0,b:{t:2,i:[{t:3}],s:"Leggi la descrizione e quali sezioni richiede."}},{t:0,b:{t:2,i:[{t:3}],s:"Copia il modello, incollalo nella tua configurazione e regola i valori."}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:"Cosa sono"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Una raccolta curata di blocchi Klipper comuni: gcode_macros (PRINT_START, PAUSE/RESUME, caricamento/scaricamento filamento, M600) e sezioni di configurazione ([input_shaper], [bed_mesh], [firmware_retraction], …). Sono punti di partenza - leggi ciascuno e adattalo alla tua macchina."}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:"Inserire un modello"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Copia un modello, poi incollalo nel tuo printer.cfg - la vista Raw del Config Editor è un punto comodo. Dopo il salvataggio, un riavvio del firmware lo applica. Controlla sempre prima i valori; i valori predefiniti qui sono ragionevoli ma non ottimizzati per la tua stampante."}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:"Sezioni richieste"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Ogni modello elenca le sezioni di configurazione che definisce o da cui dipende. Se una sezione esiste già nella tua configurazione, unisci le chiavi invece di incollare un duplicato (una sezione duplicata viene rifiutata all'avvio)."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Glossario"}},body:{t:0,b:{static:"",t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:"Modello"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Uno snippet pronto da incollare di configurazione Klipper o G-code di macro da copiare in printer.cfg."}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:"gcode_macro"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Un comando con nome che definisci nella configurazione (es. PRINT_START) che esegue una sequenza di G-code."}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:"Sezione"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Un blocco di configurazione tra [parentesi], es. [bed_mesh] - l'unità in cui è raggruppata la configurazione di Klipper."}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:"Categoria"}},all:{t:0,b:{t:2,i:[{t:3}],s:"Tutte le categorie"}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:"Copia"}},copied:{t:0,b:{t:2,i:[{t:3}],s:"Copiato!"}},requires:{t:0,b:{t:2,i:[{t:3,v:"Sezioni: "},{t:4,k:"sections"}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:"-"}}},count:{t:0,b:{t:2,i:[{t:4,k:"n"},{t:3,v:" modelli"}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:"Caricamento modelli…"}},error:{t:0,b:{t:2,i:[{t:3}],s:"Impossibile caricare i modelli."}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Nessun modello in questa categoria."}},retry:{t:0,b:{t:2,i:[{t:3}],s:"Riprova"}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:"Blocchi di configurazione"}},macros:{t:0,b:{t:2,i:[{t:3}],s:"Macro"}}}}};export{i as default};
